response:
{
  "id": "ch2-semi-linear-tree",
  "title": "第二章 半线性结构（树）：递归定义、存储表示与遍历框架",
  "subtitle": "从一对多层次关系到递归遍历的完整框架",
  "language": "zh-CN",
  "audience": "计算机相关专业本科低年级学生",
  "theme": "slate",
  "tutor": {
    "suggestions": [
      "为什么树被称为“半线性”结构，而不是线性或图结构？",
      "森林转二叉树后，为什么右孩子表示兄弟而不是右子树？",
      "先序+中序可以唯一还原二叉树，而先序+后序为什么通常不行？",
      "递归遍历二叉树时，递归工作栈和显式栈是如何一一对应的？"
    ],
    "kb": [
      {
        "pattern": "半线性结构|半线性",
        "answer": "树是半线性结构：每个节点可以有多个后继（孩子），但任意两节点之间有且仅有一条简单路径，兼具层次性与约束性。"
      },
      {
        "pattern": "递归定义|根节点|子树|森林",
        "answer": "树递归定义为：空树；或一个根节点加上若干互不相交的子树（子树集合即森林）。"
      },
      {
        "pattern": "孩子兄弟表示法|左孩子右兄弟",
        "answer": "孩子兄弟表示法把树转为二叉树：节点的左孩子指向第一个孩子，右孩子指向右邻兄弟。因此二叉树中的右孩子不表示“右子树”而表示兄弟。"
      },
      {
        "pattern": "双亲表示法|孩子表示法|孩子兄弟表示法|二叉链表",
        "answer": "双亲表示法用数组存父节点下标，适合向上查父；孩子表示法用孩子链表，适合向下查子；孩子兄弟表示法/二叉链表用两个指针，把一般树统一为二叉树处理。"
      },
      {
        "pattern": "先序遍历|中序遍历|后序遍历|层次遍历",
        "answer": "先序：根-左-右；中序：左-根-右；后序：左-右-根；层次：按层从上到下、从左到右访问。中序配合先序/后序可唯一确定二叉树。"
      },
      {
        "pattern": "堆|完全二叉树|顺序存储",
        "answer": "堆是完全二叉树的顺序存储实例，利用下标 2i/2i+1 找孩子，空间紧凑、访问局部性好；链式存储适合一般树和频繁插入删除。"
      }
    ]
  },
  "scenes": [
    {
      "id": "s1-tree-semi-linear",
      "kind": "content",
      "eyebrow": "2.1 半线性结构",
      "headline": "树：一对多层次关系与递归定义",
      "lead": "树既不是完全线性的链表，也不是任意的图；它以唯一的根到节点路径约束了层次，又以递归方式定义自身。",
      "notes": "先强调“半线性”的直觉：链表是一对一，图是多对多，树是一对多但任意两节点有唯一路径。给出递归定义时，要让学生意识到“子树本身也是树”，这是后续所有递归算法的基础。可随手画一棵根为 A、孩子为 B/C/D 的小树，说明 B 的子树与 C 的子树互不相交。",
      "blocks": [
        {
          "id": "b1_statement",
          "type": "statement",
          "intent": "点明树的半线性本质：一对多 + 任意两节点唯一路径",
          "size": "m"
        },
        {
          "id": "b2_diagram",
          "type": "diagram",
          "intent": "用层级图展示根、子树、森林的递归结构",
          "size": "l"
        },
        {
          "id": "b3_list",
          "type": "list",
          "intent": "列出树的核心性质：根唯一、子树不相交、路径唯一",
          "size": "s"
        }
      ]
    },
    {
      "id": "s2-binary-forms",
      "kind": "content",
      "eyebrow": "2.2 二叉树与转换",
      "headline": "二叉树的五种形态与树森林的相互转换",
      "lead": "二叉树是树结构中最常用、最规整的特例；孩子兄弟表示法把任意树或森林统一成二叉树，从而复用同一套算法。",
      "notes": "先讲空树、只有根、只有左子树、只有右子树、左右子树俱全五种形态。然后引入孩子兄弟表示法：左指针是孩子，右指针是兄弟。这里最容易错的是把转换后的右孩子当成“右子树”，必须用一个具体例子（根 A 有孩子 B、C，B 有孩子 D）展示右指针只连兄弟。",
      "blocks": [
        {
          "id": "b4_diagram",
          "type": "diagram",
          "intent": "图示二叉树的五种基本形态",
          "size": "m"
        },
        {
          "id": "b5_compare",
          "type": "compare",
          "intent": "左栏：原树/森林；右栏：孩子兄弟表示法转成的二叉树",
          "size": "l"
        },
        {
          "id": "b6_callout",
          "type": "callout",
          "intent": "警示：转换后右孩子表示兄弟，不是右子树",
          "size": "s"
        }
      ]
    },
    {
      "id": "s3-storage",
      "kind": "content",
      "eyebrow": "2.3 存储表示",
      "headline": "双亲、孩子、孩子兄弟与二叉链表",
      "lead": "存储方式决定操作效率：向上找父、向下找子、还是统一按二叉树处理，需要选择不同的表示法。",
      "notes": "双亲表示法用数组 parent[i] 存父节点下标，适合并查集和向上追溯；孩子表示法为每个节点维护孩子链表，适合向下遍历；孩子兄弟表示法/二叉链表用 left/right 两个指针，把一般树映射为二叉树。最后对比堆的完全二叉树顺序存储：数组下标 i 的左右孩子为 2i 与 2i+1，空间紧凑但只适合完全树。",
      "blocks": [
        {
          "id": "b7_table",
          "type": "table",
          "intent": "对比双亲、孩子、孩子兄弟/二叉链表三种存储的指针结构与典型操作复杂度",
          "size": "l"
        },
        {
          "id": "b8_compare",
          "type": "compare",
          "intent": "左：堆/完全二叉树的顺序存储；右：一般树的链式存储；说明适用场景",
          "size": "m"
        },
        {
          "id": "b9_callout",
          "type": "callout",
          "intent": "强调完全二叉树顺序存储利用下标计算父子，无需额外指针",
          "size": "s"
        }
      ]
    },
    {
      "id": "s4-traversal",
      "kind": "content",
      "eyebrow": "2.4 遍历框架",
      "headline": "先序、中序、后序与层次遍历",
      "lead": "遍历是树算法的主干；递归写法简洁，迭代写法则把隐式递归栈变成显式栈，二者本质相同。",
      "transition": "zoom",
      "notes": "先给出四种遍历的递归定义，然后用一个具体二叉树（如根 A，左 B，右 C，B 的左 D 右 E）写出四种序列。重点解释递归工作栈：每次递归调用把当前节点和局部状态压栈，返回时出栈；迭代实现就是用显式栈模拟这一过程。层次遍历用队列。可让学生运行代码并修改节点值观察序列变化。",
      "blocks": [
        {
          "id": "b10_runnable",
          "type": "runnable",
          "intent": "让学生运行并修改二叉树先序/中序/后序递归代码，观察输出序列",
          "size": "l"
        },
        {
          "id": "b11_code",
          "type": "code",
          "intent": "展示层次遍历的迭代实现（队列）",
          "size": "m"
        },
        {
          "id": "b12_callout",
          "type": "callout",
          "intent": "说明递归深度等于栈的最大高度，最坏 O(n)，空间代价不可忽视",
          "size": "s"
        }
      ]
    },
    {
      "id": "s5-reconstruct",
      "kind": "content",
      "eyebrow": "2.5 序列还原",
      "headline": "为什么中序是还原二叉树的关键",
      "lead": "遍历序列是树的“投影”；只有当中序提供左右分割信息时，才能从投影中唯一恢复树的结构。",
      "notes": "用同一组先序和中序还原二叉树：先序第一个元素是根，在中序中找到根的位置，左边是左子树、右边是右子树，递归进行。然后给出反例：先序 AB、后序 BA 可以对应 A 为根 B 为左孩子，也可以对应 A 为根 B 为右孩子，因此不唯一。这里要让学生亲手画两棵不同的树，验证它们先序后序相同。",
      "blocks": [
        {
          "id": "b13_compare",
          "type": "compare",
          "intent": "左：先序+中序可唯一还原；右：先序+后序通常不能唯一还原",
          "size": "l"
        },
        {
          "id": "b14_diagram",
          "type": "diagram",
          "intent": "用具体反例展示两棵不同二叉树具有相同先序和后序",
          "size": "m"
        },
        {
          "id": "b15_callout",
          "type": "callout",
          "intent": "指出中序的价值：给出根节点左右子树的精确划分",
          "size": "s"
        }
      ]
    },
    {
      "id": "s6-induction",
      "kind": "content",
      "eyebrow": "2.6 数学归纳",
      "headline": "用数学归纳法证明树的基本性质",
      "lead": "树的递归定义天然适合数学归纳法：先验证基础情形，再假设子树成立并推导整棵树。",
      "notes": "以“n 个节点的树有 n-1 条边”为例：基础 n=1 时边数为 0；归纳假设每棵子树满足；整棵树的边数 = 各子树边数之和 + 子树个数 = Σ(n_i-1)+k = n-1。再给出高度、叶子数等性质的证明思路。强调归纳假设就是递归调用能正确返回的数学保证。",
      "blocks": [
        {
          "id": "b16_formula",
          "type": "formula",
          "intent": "给出节点数、边数、高度、叶子数等常用等式",
          "size": "m"
        },
        {
          "id": "b17_flow",
          "type": "flow",
          "intent": "展示数学归纳法的三步：基例、归纳假设、归纳步骤",
          "size": "m"
        },
        {
          "id": "b18_list",
          "type": "list",
          "intent": "列举可用归纳法证明的典型树性质",
          "size": "s"
        }
      ]
    },
    {
      "id": "s7-abstraction",
      "kind": "content",
      "eyebrow": "2.7 应用与抽象",
      "headline": "从现实问题中抽象出节点与关系",
      "lead": "文件系统、组织结构、XML/JSON、决策树、索引等看似不同的场景，本质都是把实体抽象为节点、把从属或分类关系抽象为边。",
      "notes": "每个应用都要指出“节点是什么”和“边代表什么关系”。例如文件系统中节点是文件/目录，边是包含关系；决策树中节点是判断条件或类别，边是判断结果；B+ 树索引中节点是键值区间，边是子区间指向。最后总结抽象方法：找唯一根、找一对多关系、检查是否有环。",
      "blocks": [
        {
          "id": "b19_grid",
          "type": "grid",
          "intent": "展示文件系统、组织结构、XML/JSON、决策树、索引等典型应用",
          "size": "l"
        },
        {
          "id": "b20_list",
          "type": "list",
          "intent": "给出从问题描述抽象为树模型的三步：识别根、识别父子关系、验证无环与唯一路径",
          "size": "m"
        },
        {
          "id": "b21_callout",
          "type": "callout",
          "intent": "提醒：不是所有层次数据都适合用树，若存在多父或共享子结构则应考虑 DAG 或图",
          "size": "s"
        }
      ]
    },
    {
      "id": "s8-quiz",
      "kind": "quiz",
      "headline": "随堂检验",
      "notes": "通过选择题检查学生对半线性、孩子兄弟转换、遍历序列还原三个核心点的掌握。可让学生先独立思考，再简要讲解每个选项的陷阱。",
      "blocks": [
        {
          "id": "b22_quiz",
          "type": "quiz",
          "intent": "考察半线性结构、孩子兄弟转换、遍历序列还原三个核心知识点",
          "size": "l"
        }
      ]
    }
  ]
}
